        if($limit<1||$limit>100)throw new InvalidArgumentException('Invalid batch limit');$candidates=$this->tx(function()use($issuer,$actor,$limit){$this->auth($issuer,$actor);$p=$this->policy($issuer,true);if((int)$p['configured_by']!==$actor)throw new DomainException('company_connect_api_denied');$read=fn(int$after,int$contact)=>$this->rows('SELECT t.id ticket_id,c.id contact_id FROM '.$this->p.'company_tickets t JOIN '.$this->p.'company_portal_tickets q ON q.issuer_id=t.issuer_id AND q.ticket_id=t.id AND q.visible=1 JOIN '.$this->p.'contacts c ON c.userid=t.client_id AND c.active=1 JOIN '.$this->p.'contact_permissions n ON n.userid=c.id AND n.permission_id=5 LEFT JOIN '.$this->p.'company_ticket_connect_messages m ON m.issuer_id=t.issuer_id AND m.ticket_id=t.id AND m.contact_id=c.id WHERE t.issuer_id=? AND '.NativeCompanyTicketVisibility::predicate($this->db,$this->p,'t.issuer_id','t.id').' AND t.id>? AND m.message_key IS NULL AND (t.id>? OR (t.id=? AND c.id>?)) ORDER BY t.id,c.id LIMIT '.$limit,[$issuer,$p['first_ticket_id'],$after,$after,$contact]);$rows=$read((int)$p['scan_ticket_id'],(int)$p['scan_contact_id']);if(!$rows)$rows=$read((int)$p['first_ticket_id'],0);$last=$rows?end($rows):['ticket_id'=>$p['first_ticket_id'],'contact_id'=>0];IssuerStorage::query($this->db,'UPDATE '.$this->p.'company_ticket_connect_policies SET scan_ticket_id=?,scan_contact_id=? WHERE issuer_id=?',[(int)$last['ticket_id'],(int)$last['contact_id'],$issuer]);return$rows;});$count=0;foreach($candidates as$c){try{$revision=$this->tx(function()use($issuer,$actor,$c){[$s]=$this->source($issuer,$actor,(int)$c['ticket_id'],(int)$c['contact_id']);return self::hash($s);});$this->queue($issuer,$actor,(int)$c['ticket_id'],(int)$c['contact_id'],$revision,$encrypt);$count++;}catch(DomainException $ignored){}}return$count;
    }
    /** Trusted sessionless scheduling bookkeeping only; never authorizes or sends a message. */
    public function rotateDiscovery(int $issuer):void{$this->tx(function()use($issuer){IssuerStorage::query($this->db,'UPDATE '.$this->p.'company_ticket_connect_policies SET scan_count=scan_count+1 WHERE issuer_id=? AND enabled=1',[$issuer]);});}
    public function blockPending(int $issuer,string $key):void{$this->tx(function()use($issuer,$key){IssuerStorage::query($this->db,"UPDATE ".$this->p."company_ticket_connect_messages SET status='blocked',updated_at=? WHERE issuer_id=? AND message_key=? AND status='pending'",[gmdate('Y-m-d H:i:s'),$issuer,$key]);});}
}
